//! 📦️ A completed native initializer lends the unchanged Store allocation without a second birth.
use semio_framework_job::*;
use semio_framework_os_kernel as store;
use semio_framework_plugin_window_config::{WindowConfigInitializationOwners,WindowConfigOwner};
use semio_framework_value::RetainedCloneGrant;
use store::ArtifactStoreInitializationAuthority;
const TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096};
#[test]
fn original_initializer_box_handoff_has_no_allocation_or_release(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let actor=store::ActorId("boxed-native-source".into());let envelope=semio_framework_async::block_on(store::create_config_envelope::<crate::fixture::State,crate::fixture::Mutation>(crate::fixture::Owner::SCHEMA,"boxed-native-source",crate::fixture::State::default(),None));let mut init=store::ArtifactStoreReplayInitializer::<crate::fixture::State,crate::fixture::Mutation,WindowConfigInitializationOwners<crate::fixture::Owner>>::new(envelope,crate::fixture::Owner::SCHEMA,OperationId(4129),Generation(62),actor);let mut caller=OriginalJobFixtureCaller::admit(OperationId(4129),Generation(62),RetainedCloneGrant{maximum_items:1<<28,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<28,maximum_release_bytes:1<<28,maximum_depth:4096},default_now_us,u64::MAX,1<<28);let mut decoder=OriginalJobDecodeOwner::empty();for index in 0..1048576{let (ready,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut decoder,|cx|Ok(matches!(init.step(cx)?,Some(JobOutcomeBorrow::Complete{..})))));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));if ready.unwrap(){break}assert!(index<1048575)}let original=std::ptr::from_ref(init.candidate.as_ref().unwrap().as_ref());let(candidate,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||init.take_boxed_candidate());let candidate=candidate.unwrap();assert_eq!(std::ptr::from_ref(candidate.as_ref()),original);assert_eq!(heap.requested_bytes,law["handoffAllocations"].as_u64().unwrap()as usize);assert_eq!(heap.released_bytes,law["handoffReleases"].as_u64().unwrap()as usize);assert_eq!(candidate.snapshot().unwrap().zoom,law["initialZoom"].as_f64().unwrap());assert!(init.take_boxed_candidate().is_none());let mut candidate=Some(candidate);for index in 0..1048576{if init.terminal_is_empty(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut decoder,|cx|cx.with_original_retirement(|cx|init.close_step(cx))));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap();assert!(index<1048575)}for index in 0..1048576{if candidate.as_ref().unwrap().close_owned_store_terminal_is_empty(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut decoder,|cx|cx.with_original_retirement(|cx|{let store=candidate.as_mut().unwrap();let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|g|store.close_owned_store_step(g))?;Ok(())})));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap();assert!(index<1048575)}let bytes=std::mem::size_of_val(candidate.as_ref().unwrap().as_ref());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut decoder,|cx|cx.with_original_retirement(|cx|{let d=semio_framework_value::RetirementDemand{copy_bytes:std::mem::size_of_val(&candidate),release_bytes:bytes,depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{candidate=None;Ok(semio_framework_value::RetainedCloneStep::Progress(semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:bytes,..Default::default()}))})?;Ok(())})));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap();while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(TURN);}
